INSERT INTO `categories` VALUES (1,'Bút khảm','Các mẫu bút ký được trang trí bằng kỹ thuật khảm trai, khảm ốc hoặc xà cừ. Sản phẩm có tính thẩm mỹ cao, phù hợp làm quà tặng doanh nhân, quà lưu niệm và sử dụng trong văn phòng.','2026-06-09 02:03:25','2026-06-09 02:06:27'),(2,'Đĩa gỗ','Các mẫu đĩa trang trí được chế tác từ gỗ tự nhiên, bề mặt khảm trai hoặc xà cừ với nhiều chủ đề truyền thống, phong cảnh và phong thủy. Sản phẩm thường được trưng bày trên kệ, tủ hoặc dùng làm quà tặng.','2026-06-09 02:03:50','2026-06-09 02:06:34'),(3,'Hộp đựng trang sức','Hộp gỗ dùng để bảo quản trang sức và vật dụng nhỏ, được trang trí bằng họa tiết khảm trai, khảm ốc hoặc chạm khắc thủ công. Sản phẩm vừa tiện dụng vừa có giá trị trang trí.','2026-06-09 02:04:06','2026-06-09 02:06:40'),(4,'Hộp gỗ đựng giấy ăn','Hộp đựng giấy ăn bằng gỗ tự nhiên, được khảm trai, khảm ốc hoặc chạm hoa văn truyền thống. Sản phẩm giúp không gian bàn ăn, phòng khách và phòng làm việc trở nên sang trọng hơn.','2026-06-09 02:04:19','2026-06-09 02:06:47'),(5,'Hộp khảm trai','Nhóm các loại hộp gỗ thủ công như hộp mứt, hộp quà, hộp đựng vật dụng và hộp trang trí. Bề mặt sản phẩm được khảm trai hoặc xà cừ với hoa văn truyền thống, phù hợp sử dụng trong gia đình và làm quà tặng.','2026-06-09 02:04:42','2026-06-09 02:04:42'),(6,'Khay khảm','Các loại khay gỗ dùng để bày trà, bánh, đồ tiếp khách hoặc vật phẩm trang trí. Sản phẩm được khảm trai, khảm ốc hoặc xà cừ với hoa văn tinh xảo, tạo điểm nhấn cho không gian sử dụng.','2026-06-09 02:04:59','2026-06-09 02:07:17'),(7,'Lọ lục bình','Các mẫu lọ và lục bình bằng gỗ được tiện tạo dáng, sau đó trang trí bằng kỹ thuật khảm trai hoặc khảm ốc. Sản phẩm thường được trưng bày theo cặp tại phòng khách, phòng thờ hoặc không gian nội thất truyền thống.','2026-06-09 02:05:18','2026-06-09 02:07:33'),(8,'Lọ trà','Lọ gỗ có nắp dùng để bảo quản chè, trà khô và các loại thảo mộc. Bề mặt được khảm trai hoặc xà cừ với họa tiết truyền thống, vừa giữ công năng bảo quản vừa tăng giá trị thẩm mỹ.','2026-06-09 02:05:35','2026-06-09 02:43:45'),(9,'Quà tặng khảm trai','Các sản phẩm thủ công khảm trai được lựa chọn và đóng gói thành quà tặng, phù hợp dành cho đối tác, khách hàng, người thân hoặc các dịp lễ, khai trương và kỷ niệm.','2026-06-09 02:05:48','2026-06-09 02:05:48'),(10,'Sập gụ','Các mẫu sập gụ bằng gỗ tự nhiên có kích thước lớn, được chạm khắc và khảm trai hoặc khảm ốc công phu. Sản phẩm mang phong cách nội thất truyền thống, thường sử dụng trong phòng khách hoặc không gian nhà cổ.','2026-06-09 02:06:20','2026-06-09 02:06:20'),(11,'Tranh chữ khảm','Các bức tranh chữ thư pháp như Phúc, Lộc, Thọ, Tâm hoặc Đức được thể hiện bằng kỹ thuật khảm trai, khảm ốc trên nền gỗ. Sản phẩm mang ý nghĩa phong thủy và thường được dùng làm quà tặng, tranh treo phòng khách hoặc phòng thờ.','2026-06-09 02:07:52','2026-06-09 02:08:04'),(12,'Tranh khảm','Nhóm tranh nghệ thuật được chế tác trên nền gỗ và trang trí bằng vỏ trai, vỏ ốc hoặc xà cừ. Chủ đề đa dạng gồm phong cảnh, lịch sử, nhân vật, chim hoa và biểu tượng phong thủy, phù hợp trang trí nhiều không gian.','2026-06-09 02:08:17','2026-06-09 02:08:29'),(13,'Đốc lịch','Sản phẩm treo tường kết hợp phần tranh gỗ khảm trai với vị trí gắn lịch. Đốc lịch thường mang các chủ đề chúc phúc, phong thủy và văn hóa truyền thống, phù hợp làm quà Tết hoặc trang trí gia đình.','2026-06-09 02:08:47','2026-06-09 02:08:47'),(14,'Tủ chè','Tủ chè khảm ốc thủ công, kích thước lớn','2026-06-09 03:00:15','2026-06-09 03:00:15');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
