/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,'Bút ký khảm trai kèm hộp gỗ hoa văn tứ quý','Mẫu bút ký thanh lịch đặt trong hộp gỗ thủ công, bề mặt trang trí hoa lá khảm xà cừ. Sản phẩm thích hợp làm quà tặng cá nhân, quà tri ân hoặc quà tặng sự kiện.',300000.00,50000.00,219000.00,100,0,'Bút khảm vỏ trai/xà cừ, khoen kim loại mạ vàng; hộp gỗ tự nhiên lót nhung đỏ, mặt hộp khảm trai',1,'2026-06-09 02:16:25','2026-06-09 02:18:21'),(2,'Bộ bút ký khảm trai kèm ống cắm bút','Bộ bút ký thủ công nổi bật với sắc xà cừ óng ánh, đi kèm ống cắm bút trang trí họa tiết sơn thủy. Phù hợp đặt tại bàn làm việc, làm quà tặng doanh nhân, đối tác hoặc quà lưu niệm cao cấp.',699000.00,200000.00,499000.00,100,0,'Thân bút khảm vỏ trai/xà cừ, chi tiết kim loại mạ màu vàng; ống cắm bút cốt gỗ sơn đen khảm trai',1,'2026-06-09 02:17:33','2026-06-09 02:17:33'),(3,'Đĩa Gỗ Khảm Ốc \"Khuê Văn Các\" – Biểu Tượng Di Sản & Nghệ Thuật Tinh Xảo','Giao thoa giữa bề dày lịch sử và tư duy thẩm mỹ đương đại, Đĩa Gỗ Khảm Ốc \"Khuê Văn Các\" không chỉ là một vật phẩm trang trí, mà còn là một tác phẩm nghệ thuật mang đậm hồn cốt Việt. Được chế tác từ những đôi bàn tay tài hoa của các nghệ nhân làng nghề truyền thống, sản phẩm mang đến vẻ đẹp tĩnh lặng, sang trọng, là điểm nhấn hoàn hảo cho những không gian sống trân trọng giá trị văn hóa.',20000000.00,8000000.00,14999000.00,10,0,'Được làm từ gỗ mun, khảm ốc và xà cừ',2,'2026-06-09 02:23:37','2026-06-09 02:23:37'),(4,'Đĩa Gỗ Khảm Ốc \"Tùng Lộc Trường Tồn\" – Kiệt Tác Của Sự Thịnh Vượng','Tác phẩm \"Tùng Lộc Trường Tồn\" là một bản hòa ca tuyệt đẹp giữa vẻ đẹp thiên nhiên và kỹ nghệ chế tác đỉnh cao. Vượt ra khỏi giới hạn của một vật phẩm trang trí thuần túy, chiếc đĩa mang đến một luồng sinh khí quyền quý, tĩnh tại, sẵn sàng trở thành mảnh ghép hoàn hảo cho những không gian kiến trúc theo đuổi ngôn ngữ thiết kế hiện đại, thanh lịch.',18500000.00,6500000.00,14650000.00,10,0,'Đĩa được làm từ gỗ trắc, khảm ốc đỏ và xà cừ',2,'2026-06-09 02:26:21','2026-06-09 02:26:21'),(5,'Đĩa Gỗ Khảm Ốc \"Bát Tiên Tụ Hội\"','Mang trong mình tinh hoa của nghệ thuật khảm xà cừ, tác phẩm \"Bát Tiên Tụ Hội\" là một minh chứng hoàn hảo cho sự trường tồn của thẩm mỹ truyền thống. Tác phẩm không chỉ lưu giữ trọn vẹn kỹ nghệ điêu luyện của các nghệ nhân mà còn là một điểm nhấn thị giác đầy quyền lực, mang lại sự tĩnh tại và thanh tao cho những không gian sống hướng đến sự tinh giản.',15000000.00,6000000.00,12690000.00,10,0,'Gỗ Hương, Khảm ốc Xanh, đỏ Singapore',2,'2026-06-09 02:29:34','2026-06-09 02:29:34'),(6,'Đĩa Gỗ Khảm Ốc \"Thuận Buồm Xuôi Gió\" – Khát Vọng Vương Tầm','Biểu tượng kinh điển của sự hanh thông và ý chí kiên cường nay được tái hiện đầy kiêu hãnh trên tác phẩm Đĩa Gỗ Khảm Ốc \"Thuận Buồm Xuôi Gió\". Sự kết hợp hoàn hảo giữa kỹ nghệ khảm trai truyền thống và tư duy thẩm mỹ tối giản biến vật phẩm này thành món quà ngoại giao cao cấp hoặc điểm nhấn quyền lực cho không gian làm việc hiện đại.',16999000.00,6400000.00,1300000.00,10,0,'Đĩa gỗ mun, khảm ốc đỏ',2,'2026-06-09 02:32:41','2026-06-09 02:32:41'),(7,'Đĩa Gỗ Khảm Ốc \"Trúc Lâm Thất Hiền\"','Mang cả một trời điển tích lịch sử và triết lý sống an nhiên vào không gian nội thất đương đại, tác phẩm \"Trúc Lâm Thất Hiền\" là hiện thân của sự thanh tao và trí tuệ đỉnh cao. Tác phẩm sinh ra dành cho những gia chủ yêu thích chiều sâu văn hóa Đông Phương nhưng vẫn mong muốn giữ được tinh thần tinh giản, nhẹ nhàng của ngôi nhà hiện đại.',12000000.00,4000000.00,6500000.00,10,0,'Đĩa gỗ mun, khảm ốc xanh, cửu khổng',2,'2026-06-09 02:33:43','2026-06-09 02:33:43'),(8,'Đĩa Gỗ Khảm Ốc \"Cửu Ngư Quần Hội\" – Khơi Nguồn Vượng Khí','Sống động, rực rỡ và ngập tràn năng lượng tích cực là những gì tác phẩm \"Cửu Ngư Quần Hội\" mang lại. Trải qua hàng chục giờ cẩn trọng cắt lộng thủ công, các nghệ nhân đã biến các mảng vỏ ốc vô tri thành một bức tranh thủy sinh đầy nghệ thuật, làm bừng sáng mọi góc nhìn trong không gian kiến trúc tối giản.',11500000.00,3500000.00,7600000.00,20,0,'Đĩa gỗ mun, khảm cửu khổng, xà cừ, ốc xanh',2,'2026-06-09 02:35:38','2026-06-09 02:35:38'),(9,'Hộp Gỗ Đựng Đồ Cá Nhân \"Mộc Tâm\"','Đơn giản trong đường nét nhưng quyền lực trong công năng, Hộp Gỗ Cá Nhân \"Mộc Tâm\" là món phụ kiện tối ưu để lưu trữ những tạo tác giá trị nhất của bạn – từ đồng hồ, trang sức cao cấp cho đến tài liệu quan trọng. Thiết kế hướng đến sự vuông vức, tinh gọn, tôn vinh trọn vẹn vẻ đẹp nguyên bản của những đường vân gỗ tự nhiên.',2500000.00,600000.00,2000000.00,50,0,'Gỗ hương',3,'2026-06-09 02:37:54','2026-06-09 02:37:54'),(10,'Hộp Khăn Giấy Chạm Khắc \"Mộc Hoa\"','Biến những vật dụng quen thuộc hàng ngày thành một tác phẩm nghệ thuật thu nhỏ, Bộ sưu tập Hộp khăn giấy \"Mộc Hoa\" mang đến nét chấm phá thanh lịch cho bàn trà phòng khách hoặc không gian làm việc. Đây là lời khẳng định về gu thẩm mỹ tinh tế của gia chủ, nơi những chi tiết nhỏ nhất cũng được chăm chút tỉ mỉ.',300000.00,100000.00,239000.00,100,0,'Gỗ mun',4,'2026-06-09 02:38:59','2026-06-09 02:38:59'),(11,'Khay Mứt Tết Khảm Ốc Bát Giác \"Bình An Viên Mãn\"','Đỉnh cao của nghệ thuật tiếp khách ngày Xuân được gói trọn trong Khay Mứt Tết Bát Giác Khảm Ốc. Với tạo hình 8 cạnh cân xứng đại diện cho sự may mắn, tác phẩm là sự kết hợp hoàn mỹ giữa công năng tiện dụng và giá trị thủ công mỹ nghệ cao cấp, sẵn sàng trở thành tâm điểm của mọi lời tán thưởng trong dịp sum vầy.',3500000.00,1000000.00,2500000.00,10,0,'Gỗ mun, khảm ốc xanh, cửu khổng',5,'2026-06-09 02:40:07','2026-06-09 02:40:07'),(12,'Khay Trà Gỗ Khảm Ốc Chân Quỳ \"Sơn Thủy Hữu Tình\"','Là biểu tượng cho nghệ thuật thưởng trà cao cấp, Khay Trà Chân Quỳ \"Sơn Thủy Hữu Tình\" kết hợp hoàn hảo giữa kiểu dáng quý phái xưa và tinh thần tối giản nay. Tác phẩm không chỉ đơn thuần là một khay trà, mà là nét vẽ định hình đẳng cấp cho toàn bộ không gian phòng khách hay phòng trà hiện đại của gia chủ.',15000000.00,6000000.00,11900000.00,10,0,'Gỗ Hương, Khảm ốc đỏ, ốc xanh',6,'2026-06-09 02:41:57','2026-06-09 02:41:57'),(13,'Cặp Lọ Hoa Gỗ Khảm Ốc \"Mai Điểu Triều Dương\"','Sở hữu dáng hình uyển chuyển cùng sắc độ tương phản đỉnh cao, Cặp Lọ Hoa Gỗ \"Mai Điểu Triều Dương\" là điểm nhấn đối xứng đầy quyền lực cho các không gian nội thất cao cấp. Tác phẩm mang đến sự bề thế, trang nghiêm nhưng không kém phần thanh thoát, đặc biệt phù hợp khi bài trí trên tủ console hoặc kệ tivi phòng khách.',23900000.00,12000000.00,17600000.00,10,0,'Gỗ trắc, khảm ốc xanh, cửu khổng',7,'2026-06-09 02:43:11','2026-06-09 02:43:11'),(14,'Ống Đựng Trà Gỗ Khảm Ốc \"Tiều Phu Quy Ẩn\"','Nằm trong bộ sưu tập phụ kiện bàn trà xa xỉ, bộ đôi ống đựng trà bằng gỗ tự nhiên là lời khẳng định về một phong cách sống duy mỹ. Sản phẩm không chỉ giữ trọn hương vị thượng hạng của những lá trà quý nhờ kết cấu nắp khít hoàn hảo, mà còn là một tác phẩm nghệ thuật mini trưng bày đầy cuốn hút.',3000000.00,1200000.00,2200000.00,20,0,'Gỗ hương, Khảm ốc đỏ',8,'2026-06-09 02:44:58','2026-06-09 02:47:01'),(15,'Ống Đựng Trà Gỗ Khảm Ốc \"Mộc Trà\"','Nằm trong bộ sưu tập phụ kiện bàn trà xa xỉ, bộ đôi ống đựng trà bằng gỗ tự nhiên là lời khẳng định về một phong cách sống duy mỹ. Sản phẩm không chỉ giữ trọn hương vị thượng hạng của những lá trà quý nhờ kết cấu nắp khít hoàn hảo, mà còn là một tác phẩm nghệ thuật mini trưng bày đầy cuốn hút.',3500000.00,1300000.00,2300000.00,20,0,'Gỗ hương, khảm ốc đỏ',8,'2026-06-09 02:46:43','2026-06-09 02:46:43'),(16,'Hộp Quà Tặng Quý Ông \"Vanguard\" Khảm Xà Cừ – Khí Chất Độc Bản','Định nghĩa lại nghệ thuật quà tặng doanh nghiệp cao cấp, Giftset \"Vanguard\" là sự kết hợp hoàn mỹ giữa thời trang quý ông hiện đại và kỹ nghệ khảm xà cừ đỉnh cao. Set quà tặng được thiết kế dành riêng cho các nhà lãnh đạo, đối tác chiến lược hoặc những người trân trọng lối sống duy mỹ, tinh tế trong từng chi tiết nhỏ nhất.',1500000.00,450000.00,1190000.00,100,0,'Khảm xà cừ',9,'2026-06-09 02:50:15','2026-06-09 02:50:15'),(17,'ập Thờ Gỗ Khảm Ốc Toàn Bích \"Vạn Đại Trường Tồn\"','Là kiệt tác có quy mô bề thế nhất trong bộ sưu tập di sản, Sập Thờ Khảm Ốc Toàn Bích là sự kết tinh của hàng trăm giờ lao động nghiêm túc và kỹ nghệ cưa lộng đạt đến độ thượng thừa của các nghệ nhân làng nghề. Tác phẩm mang lại một trường năng lượng trang nghiêm, quyền quý, là trung tâm linh hồn của không gian thờ tự cao cấp.',99000000.00,45000000.00,79000000.00,3,0,'Gỗ Trắc, Khảm ốc đỏ Singapore',10,'2026-06-09 02:51:37','2026-06-09 02:51:37'),(18,'Tranh Gỗ Khảm Ốc \"Chữ Phúc Hóa Long\"','Vượt lên trên những bức tranh chữ thông thường, tác phẩm \"Chữ Phúc Hóa Long\" là một cuộc chơi nghệ thuật tạo hình đầy sáng tạo. Bức tranh là sự lựa chọn lý tưởng để làm điểm nhấn phong thủy, xóa tan sự đơn điệu của những mảng tường trống trong các căn hộ, biệt thự mang phong cách tân cổ điển hoặc tối giản hiện đại.',9500000.00,3500000.00,6800000.00,20,0,'Gỗ mun, Khảm ốc đỏ',11,'2026-06-09 02:52:40','2026-06-09 02:52:40'),(19,'Tranh ngang Khảm Ốc \"Bách Hạc Trường Xuân\"','Tái hiện bức tranh phong cảnh kinh điển về sự trường thọ và an khang, đại tranh \"Bách Hạc Trường Xuân\" dáng trường cuốn mang lại một không gian khoáng đạt, tĩnh tại cho phòng khách lớn hoặc phòng làm việc của các nhà lãnh đạo.',20000000.00,6500000.00,15000000.00,10,0,'Gỗ Hương, Khảm ốc xanh',12,'2026-06-09 02:53:46','2026-06-09 02:53:46'),(20,'Tranh ngang Khảm Ốc \"Vinh Quy Bái Tổ\"','Mang ý nghĩa nhân văn sâu sắc về truyền thống \"Uống nước nhớ nguồn\", đại tranh \"Vinh Quy Bái Tổ\" dạng trường cuốn là bức họa kể về hành trình vinh hiển của vị tân khoa trạng nguyên trở về làng cũ bái tạ tổ tiên. Đây là tác phẩm mang tính biểu tượng cao nhất về sự đỗ đạt, thành danh và trí tuệ.',21000000.00,10000000.00,17000000.00,10,0,'Gỗ Hương, Khảm ốc đỏ, ốc xanh',12,'2026-06-09 02:55:05','2026-06-09 02:55:05'),(21,'Tranh Gỗ Khảm Ốc \"Chùa Một Cột\"','Được ví như đóa sen tinh khiết vươn lên từ mặt nước, biểu tượng kiến trúc ngàn năm tuổi của Thăng Long – Hà Nội nay được tái hiện đầy thoát tục trên tác phẩm Tranh Gỗ Khảm Ốc \"Chùa Một Cột\". Bức tranh mang lại một khoảng lặng an yên, thư thái, vô cùng phù hợp để điều hòa không gian sống mang phong cách tối giản đương đại.',9000000.00,4500000.00,6500000.00,12,0,'Gỗ Hương, Khảm ốc đỏ',12,'2026-06-09 02:57:16','2026-06-09 02:57:16'),(22,'Tranh Gỗ Khảm Ốc \"Thuận Buồm Xuôi Gió\"','Vẫn giữ trọn vẹn thông điệp về sự hanh thông và vượng khí, phiên bản Tranh Khung Vuông \"Thuận Buồm Xuôi Gió\" mang đến một cảm giác vững chãi, quy chuẩn và cân đối hơn cho mảng tường trang trí.',10000000.00,4500000.00,8000000.00,20,0,'Gỗ Hương, Khảm ốc Đỏ',12,'2026-06-09 02:58:07','2026-06-09 02:58:07'),(23,'Tranh Treo Lịch Gỗ Khảm Ốc \"Bát Tiên Quần Hội\"','Nâng tầm chiếc block lịch quen thuộc ngày Tết thành một tác phẩm nghệ thuật gia bảo truyền đời, Tranh Treo Lịch Khảm Ốc \"Bát Tiên Quần Hội\" là sự lựa chọn hoàn hảo để trang hoàng phòng khách mỗi dịp Xuân về, vừa giữ nét văn hóa truyền thống vừa mang hơi thở thượng lưu.',5000000.00,1500000.00,3000000.00,50,0,'Gỗ trắc, Khảm ốc đỏ',13,'2026-06-09 02:59:13','2026-06-09 02:59:13'),(24,'Tủ Chè Gỗ Gụ Khảm Trai \"Đại Cảnh Liên Hoàn\"','Là một trong những tạo tác quy mô và đòi hỏi kỹ nghệ khắt khe nhất, chiếc Tủ Chè Khảm Trai Toàn Bích là món nội thất tuyên ngôn cho sự giàu sang, bề thế và gu thẩm mỹ đỉnh cao của gia chủ. Sản phẩm đóng vai trò là tâm điểm thị giác cho những không gian đại sảnh, biệt thự hay phòng khách sang trọng.',45000000.00,25000000.00,37000000.00,5,0,'Gỗ Trắc, Khảm ốc đỏ',14,'2026-06-09 03:01:10','2026-06-09 03:01:10'),(25,'Bộ Tranh Tứ Quý \"Tứ Dân Đại Ẩn\"','Khác biệt với những bộ tranh phong cảnh thông thường, Bộ tranh \"Tứ Dân\" mang tính triết lý sâu sắc, khắc họa lối sống an nhiên, tự tại của người quân tử thời xưa giữa thiên nhiên khoáng đạt.',25000000.00,12000000.00,21000000.00,10,0,'Gỗ Hương, Khảm ốc đỏ',12,'2026-06-09 03:02:24','2026-06-09 03:02:24'),(26,'Bộ Tranh Tứ Quý \"Tùng Cúc Trúc Mai\"','Là bộ tranh phong thủy kinh điển đại diện cho bốn mùa Xuân – Hạ – Thu – Đông, \"Tùng Cúc Trúc Mai\" là biểu tượng của sự luân chuyển may mắn, bền bỉ và khí chất kiên cường của gia chủ.',21000000.00,11000000.00,17000000.00,10,0,'Gỗ Hương, Khảm ốc đỏ',12,'2026-06-09 03:03:10','2026-06-09 03:03:10');
