LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (1,2,1,5,'Tranh rất đẹp, khảm tỉ mỉ từng chi tiết. Màu sắc tự nhiên của trai biển lung linh hơn ảnh thật. Giao hàng cẩn thận, đóng gói kỹ. Shop hỗ trợ lắp đặt tận nơi. Sẽ ủng hộ tiếp!','2025-02-13 03:00:00'),(2,3,15,5,'Bộ tứ quý khảm ốc đẹp xuất sắc, chất lượng gỗ gụ tốt, ốc xà cừ sáng bóng. Treo phòng khách ai nhìn cũng khen. Giao hàng đúng hẹn. Cảm ơn shop!','2025-02-18 07:00:00'),(3,4,13,4,'Sản phẩm chất lượng cao, xứng đáng tầm giá. Chỉ tiếc thời gian giao hàng hơi lâu do làm thủ công. Shop tư vấn nhiệt tình, hỗ trợ chọn kích thước phù hợp.','2025-02-26 02:00:00'),(4,5,32,5,'Tranh Chùa Một Cột khảm rất tinh tế, tặng đối tác nước ngoài họ rất thích. Khen là quà lưu niệm Việt Nam đẹp nhất họ từng nhận. Chắc chắn sẽ mua thêm.','2025-03-08 03:00:00'),(5,7,4,5,'Tranh Mừng Thọ tặng bố tôi 70 tuổi, ông rất xúc động. Kích thước đẹp, màu sắc trang nhã, khảm tinh xảo. Rất xứng đáng với giá tiền.','2025-03-19 07:00:00'),(6,8,5,5,'Bức Thuận Buồm Xuôi Gió treo văn phòng cực đẹp, toả ra năng lượng tích cực. Shop hỗ trợ lắp đặt tận nơi, rất chuyên nghiệp. Đồng nghiệp ai cũng trầm trồ.','2025-03-27 08:00:00'),(7,9,31,4,'Tranh Đền Ngọc Sơn làm quà tặng bạn bè nước ngoài, ai cũng trầm trồ. Giao hàng nhanh, đóng gói cẩn thận. Muốn thêm vài lựa chọn kích thước nhỏ hơn.','2025-04-04 02:30:00'),(8,2,75,5,'Tráp tròn gỗ trắc đẹp lắm, mua làm tráp lễ cưới, ốc xà cừ sáng lung linh. Gỗ trắc thơm tự nhiên. Mọi người khen ngợi nhiều. Sẽ mua thêm bộ tráp đầy đủ.','2025-04-27 03:00:00'),(9,6,57,5,'Hoành phi Gia Đình Hòa Thuận sơn son thếp vàng rất trang trọng. Treo phòng thờ đẹp hơn hẳn. Người bán tư vấn chữ phù hợp, hỗ trợ lắp đặt tận nhà tận tình.','2025-03-14 04:00:00'),(10,3,19,5,'Tranh Bách Phúc khảm ốc đỏ rất nổi bật, ý nghĩa sâu sắc. Mua tặng sếp nhân dịp thăng chức, sếp rất thích và treo ngay tại phòng làm việc. Cảm ơn shop đã tư vấn!','2025-04-30 02:00:00'),(12,7,29,5,'Tranh Quan Thế Âm khảm trai tinh tế và trang nghiêm. Treo ban thờ rất phù hợp, gia đình ai cũng hài lòng. Đóng gói kỹ lưỡng, giao hàng đúng hẹn.','2025-05-02 01:00:00'),(13,4,33,5,'Tranh Tháp Rùa rất đẹp và có hồn. Mua về Lào Cai treo phòng khách, bạn bè xuống chơi ai cũng ngạc nhiên. Nghề khảm trai truyền thống thật tuyệt vời!','2025-02-27 03:00:00'),(14,8,61,4,'Điếu gỗ hương khảm ốc làm quà tặng bố vợ rất được khen. Gỗ hương thơm tự nhiên, ốc khảm tinh tế. Hơi mong có thêm vài mẫu hoa văn để lựa chọn.','2025-03-27 09:00:00'),(15,2,68,5,'Bộ lót ly 4 miếng đóng hộp gỗ rất sang. Mua làm quà khai trương văn phòng bạn bè ai cũng thích. Giá hợp lý, chất lượng xuất sắc so với tầm giá.','2025-04-26 04:00:00'),(16,1,89,5,'Sản phẩm đẹp, các chi tiết rất sắc xảo','2026-06-01 01:24:59');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

